 const checkUpdate=async(manual=false)=>{if(!isDesktop())return manual&&setToast("更新检测请在 Windows 桌面版中使用");setUpdateChecking(true);try{const result=await desktopRequest<UpdateInfo>("update/check");setUpdateInfo(result);setSettings(s=>({...s,lastUpdateCheckAt:new Date().toISOString(),latestKnownVersion:result.latestVersion,latestReleaseUrl:result.releaseUrl}));if(manual)setToast(result.hasUpdate?`发现新版本 v${result.latestVersion}`:"当前已经是最新版本")}catch(e:any){if(manual)setToast(`检查更新失败：${e.message}`)}finally{setUpdateChecking(false)}};
 useEffect(()=>{(async()=>{try{const x=isDesktop()?await loadDesktopState():JSON.parse(localStorage.getItem("restaurant-v1")||"null");if(x){if(x.incomeRecords?.length){const records=x.incomeRecords.map((r:any,index:number)=>normalizeIncome({...r,id:r.id||index+1}));setIncomeRecords(records);setIncome(records.find((r:IncomeRecord)=>r.entryMode==="day"&&r.date===today)||blankIncome())}else if(x.income){const current=normalizeIncome({...x.income,id:x.income.id||1});setIncomeRecords([current]);setIncome(current)}if(x.expenses)setExpenses(x.expenses);if(x.products)setProducts(x.products);if(x.stocktakes)setStocktakes(x.stocktakes);if(x.salesRecords)setSalesRecords(x.salesRecords);if(x.reminders)setReminders(x.reminders);if(x.saleCategories)setSaleCategories(x.saleCategories);if(x.expenseCategories)setExpenseCategories(x.expenseCategories);if(x.employees)setEmployees(x.employees);if(x.payrolls){setPayrolls(x.payrolls);const current=x.payrolls.find((r:PayrollSnapshot)=>r.month===today.slice(0,7));if(current)setPayroll(current)}else if(x.payroll)setPayroll(x.payroll);if(x.suppliers)setSuppliers(x.suppliers);if(x.assets)setAssets(x.assets);if(x.settings)setSettings((s:any)=>({...s,...x.settings}))}}catch(e:any){setToast(`数据加载失败：${e.message}`)}finally{setHydrated(true)}})()},[]);
